// Demo seed — the single source for both the in-browser demo repository and
// supabase/seed.sql (generated by scripts/generate-seed.mts), so the demo and
// a freshly migrated Supabase project contain identical rows and IDs.
//
// Every person, company and number here is fictional sample data. The UI
// labels demo mode as such (PRD.md §4 F9, release-checklist PROD-022).
//
// Dates are stored as offsets from "now" so the charts always cover the last
// six months regardless of when the demo is opened. This file must stay free
// of runtime imports so Node can execute it directly for SQL generation.

import type {
  Activity,
  Invitation,
  Member,
  Profile,
  Project,
  ProjectStatus,
  Subtask,
  Task,
  TaskPriority,
  TaskStatus,
  Workspace,
  WorkspacePlan,
  WorkspaceRole,
} from "./types";

const uuid = (group: string, n: number) =>
  `${group}-0000-4000-8000-${n.toString(16).padStart(12, "0")}`;

