const DESCRIPTIONS: string[] = [
  "Agree the scope with the lead before starting. Link any research in the activity log.",
  "Acceptance: reviewed by the project lead and recorded in the project notes.",
  "Timebox to two days; raise blockers in stand-up rather than waiting.",
  "Depends on the previous milestone. Keep the first version small.",
  "",
];

function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const HOURS_PER_DAY = 24;
const PRIORITY_WEIGHTS: TaskPriority[] = ["low", "medium", "medium", "medium", "high", "high"];

function membersOf(workspaceId: string) {
  return SEED_MEMBERS.filter((m) => m.workspaceId === workspaceId).map((m) => m.userId);
}

function buildTasks(): { tasks: SeedTask[]; subtasks: SeedSubtask[] } {
  const rand = mulberry32(20260930);
  const pick = <T,>(xs: T[]) => xs[Math.floor(rand() * xs.length)];
  const tasks: SeedTask[] = [];
  const subtasks: SeedSubtask[] = [];
  const counters = new Map<string, number>();
  const columnPositions = new Map<string, number>();
  let taskSerial = 0;
  let subtaskSerial = 0;

  for (const project of SEED_PROJECTS) {
    const titles = TITLES[project.key] ?? [];
    const people = membersOf(project.workspaceId);
    const start = project.startOffsetDays ?? -project.createdDaysAgo;
    // Work on a project spreads from its start date up to today.
    const spanDays = Math.max(10, Math.min(-start, project.createdDaysAgo));

    titles.forEach((title, i) => {
      const progress = titles.length === 1 ? 1 : i / (titles.length - 1);
      const createdDaysAgo = Math.round(spanDays * (1 - progress * 0.92)) + 2;

      let status: TaskStatus;
      if (project.status === "completed") status = "done";
      else if (project.status === "planned") status = i === 0 ? "todo" : "backlog";
      else if (progress < 0.62) status = rand() < 0.92 ? "done" : "in_progress";
      else if (progress < 0.78) status = pick<TaskStatus>(["in_progress", "in_progress", "todo", "done"]);
      else status = pick<TaskStatus>(["todo", "todo", "backlog", "in_progress"]);
      if (project.status === "paused" && status === "in_progress") status = "todo";

      // Finished work completes somewhere between creation and today, so
      // completions spread across the whole six-month window.
      const completedDaysAgo =
        status === "done"
          ? Math.max(0, rand() < 0.55
            ? createdDaysAgo - 4 - Math.floor(rand() * 18)
            : Math.round(rand() * (createdDaysAgo - 3)))
          : null;
      // Roughly three in four tasks finish on or before their due date, and
      // about one in six open tasks has slipped past it.
      const dueDaysAgo =
        completedDaysAgo !== null
          ? completedDaysAgo + Math.round((rand() - 0.78) * 9)
          : rand() < 0.17
            ? 1 + Math.floor(rand() * 9)
            : -(3 + Math.floor(rand() * 38));
      const hasDue = status !== "backlog" || rand() < 0.3;

      const workspaceCount = (counters.get(project.workspaceId) ?? 0) + 1;
      counters.set(project.workspaceId, workspaceCount);
      const columnKey = `${project.workspaceId}:${status}`;
      const position = (columnPositions.get(columnKey) ?? 0) + 1000;
      columnPositions.set(columnKey, position);

      const hour = Math.floor(rand() * 9) + 1;
      const createdHoursAgo = createdDaysAgo * HOURS_PER_DAY + hour;
      const completedHoursAgo =
        completedDaysAgo === null ? null : completedDaysAgo * HOURS_PER_DAY + Math.floor(rand() * 8);
      taskSerial += 1;
      const id = uuid("d0000000", taskSerial);
      tasks.push({
        id,
        workspaceId: project.workspaceId,
        projectId: project.id,
        number: workspaceCount,
        title,
        description: pick(DESCRIPTIONS),
        status,
        priority: pick(PRIORITY_WEIGHTS),
        assigneeId: status === "backlog" && rand() < 0.5 ? null : pick(people),
        dueOffsetDays: hasDue ? -dueDaysAgo : null,
        position,
        createdHoursAgo,
        completedHoursAgo,
        updatedHoursAgo: completedHoursAgo ?? Math.max(1, createdHoursAgo - Math.floor(rand() * 48)),
      });

      if (status === "in_progress" || (status === "todo" && rand() < 0.4)) {
        const steps = ["Draft", "Review with lead", "Apply feedback"];
        steps.forEach((step, s) => {
          subtaskSerial += 1;
          subtasks.push({
            id: uuid("e0000000", subtaskSerial),
            workspaceId: project.workspaceId,
            taskId: id,
            title: step,
            done: status === "in_progress" && s === 0,
            position: (s + 1) * 1000,
            createdHoursAgo: createdHoursAgo - 1,
          });
        });
      }
    });
  }
  return { tasks, subtasks };
}

const built = buildTasks();
export const SEED_TASKS: SeedTask[] = built.tasks;
export const SEED_SUBTASKS: SeedSubtask[] = built.subtasks;

