// ---------------------------------------------------------------------------
// Materialise the seed into domain rows relative to a given "now".
// ---------------------------------------------------------------------------

export interface MaterialisedSeed {
  profiles: Profile[];
  workspaces: Workspace[];
  members: Omit<Member, "profile">[];
  invitations: Invitation[];
  projects: Project[];
  tasks: Task[];
  subtasks: Subtask[];
  activity: Activity[];
  taskCounters: Record<string, number>;
}

const HOUR_MS = 3_600_000;

export function isoDateOffset(now: Date, days: number): string {
  const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + days));
  return d.toISOString().slice(0, 10);
}

export function materialiseSeed(now: Date = new Date()): MaterialisedSeed {
  const at = (hoursAgo: number) => new Date(now.getTime() - hoursAgo * HOUR_MS).toISOString();
  const day = (days: number | null) => (days === null ? null : isoDateOffset(now, days));

  const tasks: Task[] = SEED_TASKS.map((t) => ({
    id: t.id,
    workspaceId: t.workspaceId,
    projectId: t.projectId,
    number: t.number,
    title: t.title,
    description: t.description,
    status: t.status,
    priority: t.priority,
    assigneeId: t.assigneeId,
    dueDate: day(t.dueOffsetDays),
    position: t.position,
    completedAt: t.completedHoursAgo === null ? null : at(t.completedHoursAgo),
    createdBy: t.assigneeId,
    createdAt: at(t.createdHoursAgo),
    updatedAt: at(t.updatedHoursAgo),
  }));

  const activity: Activity[] = [];
  let activitySerial = 0;
  const log = (a: Omit<Activity, "id">) => {
    activitySerial += 1;
    activity.push({ id: `seed-${activitySerial}`, ...a });
  };
  for (const t of SEED_TASKS) {
    log({
      workspaceId: t.workspaceId, taskId: t.id, actorId: t.assigneeId, kind: "created",
      fromValue: null, toValue: t.status === "backlog" ? "backlog" : "todo",
      createdAt: at(t.createdHoursAgo),
    });
    if (t.status === "in_progress" || t.status === "done") {
      log({
        workspaceId: t.workspaceId, taskId: t.id, actorId: t.assigneeId, kind: "status",
        fromValue: "todo", toValue: "in_progress",
        createdAt: at(Math.round((t.createdHoursAgo + (t.completedHoursAgo ?? t.updatedHoursAgo)) / 2)),
      });
    }
    if (t.status === "done" && t.completedHoursAgo !== null) {
      log({
        workspaceId: t.workspaceId, taskId: t.id, actorId: t.assigneeId, kind: "status",
        fromValue: "in_progress", toValue: "done", createdAt: at(t.completedHoursAgo),
      });
    }
  }

  const taskCounters: Record<string, number> = {};
  for (const t of SEED_TASKS) taskCounters[t.workspaceId] = Math.max(taskCounters[t.workspaceId] ?? 0, t.number);

  return {
    profiles: SEED_USERS.map(({ id, email, fullName }) => ({ id, email, fullName })),
    workspaces: SEED_WORKSPACES.map((w) => ({
      id: w.id, slug: w.slug, name: w.name, plan: w.plan,
      createdAt: at(w.createdDaysAgo * HOURS_PER_DAY),
    })),
    members: SEED_MEMBERS.map((m) => ({
      workspaceId: m.workspaceId, userId: m.userId, role: m.role,
      joinedAt: at(m.joinedDaysAgo * HOURS_PER_DAY),
    })),
    invitations: SEED_INVITATIONS.map((i) => ({
      id: i.id, workspaceId: i.workspaceId, email: i.email, role: i.role, invitedBy: i.invitedBy,
      createdAt: at(i.createdHoursAgo),
      expiresAt: at(i.createdHoursAgo - 30 * HOURS_PER_DAY),
    })),
    projects: SEED_PROJECTS.map((p) => ({
      id: p.id, workspaceId: p.workspaceId, key: p.key, name: p.name, description: p.description,
      status: p.status, leadId: p.leadId, budgetCents: p.budgetCents, color: p.color,
      startDate: day(p.startOffsetDays), targetDate: day(p.targetOffsetDays),
      createdAt: at(p.createdDaysAgo * HOURS_PER_DAY), updatedAt: at(p.createdDaysAgo * HOURS_PER_DAY),
    })),
    tasks,
    subtasks: SEED_SUBTASKS.map((s) => ({
      id: s.id, workspaceId: s.workspaceId, taskId: s.taskId, title: s.title, done: s.done,
      position: s.position, createdAt: at(s.createdHoursAgo),
    })),
    activity,
    taskCounters,
  };
}
